// TORRE ADMIN V1.4 — validação central da sessão e do contexto multicondomínio.
const entrada = $('Webhook - Torre Admin').first().json || {};
const body = entrada.body || {};
const me = $input.first().json || {};

const acao = String(body.acao || '').trim().toUpperCase();
const codigo = String(body.codigo_condominio || '').trim().toUpperCase();
const payload = body.payload && typeof body.payload === 'object' ? body.payload : {};
const requestId = String(body.request_id || entrada.headers?.['x-request-id'] || '').trim();

function txt(v){ return String(v ?? '').trim(); }
function perfilValido(v){ const p=txt(v).toUpperCase(); return p.includes('ADMIN') || p.includes('SINDICO') || p.includes('SÍNDICO'); }

let autorizado = Boolean(me?.ok && me?.usuario && codigo && acao);
let perfilCondo = '';
let condoEncontrado = null;
if (autorizado) {
  const lista = Array.isArray(me.condominios) ? me.condominios : [];
  condoEncontrado = lista.find(c => {
    const nested = c?.condominios || {};
    const code = txt(c?.codigo_condominio || nested?.codigo_condominio).toUpperCase();
    return code === codigo;
  }) || null;
  perfilCondo = txt(condoEncontrado?.perfil_condominio || condoEncontrado?.perfil || '');
  autorizado = Boolean(condoEncontrado && (perfilValido(me.usuario?.perfil_global) || perfilValido(perfilCondo)));
}

return [{json:{
  ok_auth: autorizado,
  codigo_condominio: codigo,
  acao,
  payload,
  request_id: requestId || null,
  auth_user_id: me?.usuario?.auth_user_id || null,
  usuario_plataforma_id: me?.usuario?.id || me?.usuario?.usuario_plataforma_id || null,
  usuario_email: me?.usuario?.email || null,
  usuario_nome: me?.usuario?.nome || null,
  perfil_global: me?.usuario?.perfil_global || null,
  perfil_condominio: perfilCondo || null,
  mensagem: autorizado ? null : 'Sessão, perfil ou condomínio não autorizado para operação administrativa.'
}}];

const base=$input.first().json||{};const p=base.payload||{};
function t(v){return String(v??'').trim()}
const categoriaCodigo=t(p.categoria_codigo),codigoArea=t(p.codigo_area),moradorId=t(p.morador_id),descricao=t(p.descricao);
const localOrigem=codigoArea?'AREA':(moradorId?'UNIDADE_MORADOR':null);
return [{json:{...base,valid:Boolean(categoriaCodigo&&descricao&&(codigoArea||moradorId)),categoria_codigo:categoriaCodigo,local_origem:localOrigem,codigo_area:codigoArea||null,morador_id:moradorId||null,descricao,mensagem:(!categoriaCodigo||!descricao||!(codigoArea||moradorId))?'Categoria, descrição e ao menos área/local ou morador/unidade são obrigatórios.':null}}];

const prep=$('Validar Referencias Ocorrencia').first().json||{};const r=$input.first().json||{};
