return [{json:erro?{ok:false,codigo:'OCORRENCIA_GRAVACAO_FALHOU',mensagem:String(erro.message||erro)}:(!id?{ok:false,codigo:'OCORRENCIA_SEM_ID',mensagem:'O banco não confirmou o ID da ocorrência.'}:{ok:true,codigo_condominio:prep.codigo_condominio,acao:'CRIAR_OCORRENCIA',ocorrencia_id:id,protocolo:protocolo,mensagem:'Ocorrência criada no banco com referências controladas.',notificacao_operacional:'PENDENTE_DE_HOMOLOGACAO'})}];

const base=$input.first().json||{};const p=base.payload||{};
const dias=Array.isArray(p.dias)?p.dias.map(x=>String(x).trim().toUpperCase()):[];
const map={DOM:'domingo',SEG:'segunda',TER:'terca',QUA:'quarta',QUI:'quinta',SEX:'sexta','SÁB':'sabado',SAB:'sabado'};
const bools={domingo:false,segunda:false,terca:false,quarta:false,quinta:false,sexta:false,sabado:false};
for(const d of dias){if(map[d])bools[map[d]]=true}
const horario=String(p.horario||'').trim();const tempo=Number(p.tempo_minutos||0);
