const exigeFoto=Boolean(p.exige_foto);const codigoArea=String(p.codigo_area||'').trim();const codigoTarefa=String(p.codigo_tarefa||'').trim().toUpperCase()||null;const modoImportacao=p.modo_importacao===true;const codigoValido=!codigoTarefa||/^[A-Z0-9][A-Z0-9_-]{1,39}$/.test(codigoTarefa);
return [{json:{...base,valid:Boolean(String(p.descricao_tarefa||'').trim()&&String(p.funcionario_id||'').trim()&&codigoArea&&dias.length&&/^\d{2}:\d{2}(:\d{2})?$/.test(horario)&&Number.isFinite(tempo)&&tempo>0&&['BAIXA','MEDIA','ALTA','URGENTE'].includes(prioridade)&&codigoValido&&(!modoImportacao||Boolean(codigoTarefa))),tarefa_id:p.tarefa_id||null,codigo_tarefa:codigoTarefa,modo_importacao:modoImportacao,descricao_tarefa:String(p.descricao_tarefa||'').trim(),funcionario_id:String(p.funcionario_id||'').trim(),codigo_area:codigoArea||null,dias,horario,tempo_minutos:Math.round(tempo),prioridade,exige_foto:exigeFoto,campos:{...bools,ativo:true}}}];

const base=$input.first().json||{},p=base.payload||{};
const tarefa=String(p.tarefa_id||'').trim(),raw=String(p.data_execucao||'').trim(),motivo=String(p.motivo||p.observacao||'').trim(),exec=String(p.execucao_id||'').trim(),requestId=String(base.request_id||'').trim(),requestValido=/^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(requestId);
const m=/^(\d{4})-(\d{2})-(\d{2})$/.exec(raw);let dataValida=false;
