return [{json:{...base,valid:Boolean(tarefa&&dataValida&&motivo&&requestValido),data_valida:dataValida,request_valido:requestValido,tarefa_id:tarefa,data_execucao:raw,motivo,execucao_id:exec||null}}];

const prep=$('Preparar TASK_ADMIN_CLOSE').first().json||{};const t=$input.first().json||{};
