const prep=$('Preparar CRIAR_OCORRENCIA').first().json||{};
function rows(n){try{return $(n).all().map(i=>i.json||{}).filter(x=>x&&Object.keys(x).length)}catch{return[]}}
function s(v){return String(v??'').trim()}
const code=s(prep.codigo_condominio).toUpperCase();
